function parseBody(body) {
  if (body && typeof body === "object") return body;

  const text = String(body ?? "").trim();
  if (!text) return null;

  // Direct JSON response
  try {
    return JSON.parse(text);
  } catch {}

  // SSE response
  let last = null;

  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed.startsWith("data:")) continue;

    const payload = trimmed.slice(5).trim();

    if (!payload || payload === "[DONE]") continue;

    try {
      last = JSON.parse(payload);
    } catch {}
  }

  return last;
}

function decodeNested(value, depth = 0) {
  if (depth > 3) return value;

  if (typeof value === "string") {
    try {
      return decodeNested(JSON.parse(value), depth + 1);
    } catch {
      return value;
    }
  }

  if (value && typeof value === "object" && !Array.isArray(value)) {
    if (typeof value.result === "string") {
      return {
        ...value,
        result: decodeNested(value.result, depth + 1)
      };
    }
  }

  return value;
}

function parseItem(r, index) {
  const body = r.body ?? r.data;
  const message = parseBody(body);

  const metadata = {
    itemIndex: index,
    rpcId: r.rpcId ?? message?.id ?? null,
    chatSessionId: r.chatSessionId ?? null,
    mcpSessionId: r.mcpSessionId ?? null,
    planIndex: r.planIndex ?? null,
    planCount: r.planCount ?? null,
    planId: r.planId ?? null,
    subQuestion: r.subQuestion ?? null,
    question: r.question ?? null,
    tool: r.selectedTool ?? r.tool ?? r.toolName ?? null,
    responseMode: r.responseMode ?? null,
    selectedTool: r.selectedTool ?? null,
    requestArguments: r.requestArguments ?? {},
    requestBody: r.requestBody ?? null
  };

  function bad(error) {
    return {
      json: {
        ...metadata,
        ok: false,
        error
      }
    };
  }

  const statusCode = Number(r.statusCode ?? 200);

  if (statusCode >= 400) {
    return bad(
      `MCP HTTP ${statusCode}: ${String(body ?? "").slice(0, 500)}`
    );
  }

  if (!message) {
    return bad("MCP response could not be parsed.");
  }

  if (message.error) {
    return bad(
      `MCP JSON-RPC error ${message.error.code}: ${message.error.message}`
    );
  }

  const result = message.result ?? {};

  const textContent = Array.isArray(result.content)
    ? result.content
        .filter(item => item.type === "text")
        .map(item => item.text)
        .join("\n")
    : "";

  if (result.isError) {
    return bad(
      `MCP tool execution error: ${textContent || "Unknown tool error"}`
    );
  }

  let data = result.structuredContent;

  if (data === undefined) {
    data = textContent || result;
  }

  data = decodeNested(data);

  if (data === null || data === undefined || data === "") {
    return bad("MCP returned no readable result.");
  }

  return {
    json: {
      ...metadata,
      ok: true,
      data
    }
  };
}

// Pair every HTTP response with its originating MCP request.
// JSON-RPC id is the primary key; input order is the fallback.
const items = $input.all();
const requests = $("Build Tool Call").all().map(item => item.json);
if (!requests.length || items.length !== requests.length) {
  throw new Error("MCP correlation failure: response count does not match request count.");
}
const requestIds = requests.map(request => request.rpcId);
if (requestIds.some(id => id === null || id === undefined) ||
    new Set(requestIds.map(String)).size !== requestIds.length) {
  throw new Error("MCP correlation failure: request RPC IDs are missing or duplicated.");
}
const parsedResponses = items.map(item => {
  const response = item.json ?? {};
  return { response, message: parseBody(response.body ?? response.data) };
});
const responseIds = parsedResponses.map(({response,message}) => {
  const statusCode = Number(response.statusCode ?? 200);
  const messageId = message?.id ?? null;
  if (messageId !== null && response.rpcId != null &&
      String(messageId) !== String(response.rpcId)) {
    throw new Error("MCP correlation failure: HTTP metadata RPC ID differs from JSON-RPC response ID.");
  }
  if (messageId === null && statusCode < 400) {
    throw new Error("MCP correlation failure: successful response has no JSON-RPC ID.");
  }
  return messageId;
}).filter(id => id !== null);
if (new Set(responseIds.map(String)).size !== responseIds.length) {
  throw new Error("MCP correlation failure: duplicate response RPC IDs.");
}
for (const id of responseIds) {
  if (!requestIds.some(requestId => String(requestId) === String(id))) {
    throw new Error("MCP correlation failure: response RPC ID has no matching request.");
  }
}

return items.map((item, index) => {
  const response = item.json ?? {};
  const message = parsedResponses[index].message;
  const rpcId = message?.id ?? response.rpcId ?? null;
  const statusCode = Number(response.statusCode ?? 200);
  // Positional pairing is restricted to HTTP transport failures without a
  // JSON-RPC body. Successful responses must match by JSON-RPC ID.
  const request = rpcId !== null
    ? requests.find(candidate => String(candidate.rpcId) === String(rpcId))
    : statusCode >= 400 ? requests[index] : null;
  if (!request) {
    throw new Error("MCP correlation failure: response could not be paired with its originating request.");
  }

  const enriched = {
    ...response,
    // For a transport-level HTTP failure without a JSON-RPC body, preserve
    // the request ID only after the one-to-one positional transport pairing.
    rpcId: rpcId ?? request.rpcId,
    chatSessionId: request.chatSessionId ?? null,
    mcpSessionId: request.mcpSessionId ?? null,
    planIndex: request.planIndex ?? index,
    planCount: request.planCount ?? requests.length,
    planId: request.planId ?? `plan_${index + 1}`,
    subQuestion: request.subQuestion ?? null,
    question: request.question ?? null,
    selectedTool: request.selectedTool ?? null,
    responseMode: request.responseMode ?? null,
    requestArguments: request.rpcBody?.params?.arguments ?? {},
    requestBody: request.rpcBody ?? null
  };

  try {
    return parseItem(enriched, index);
  } catch (error) {
    return {
      json: {
        itemIndex: index,
        rpcId,
        chatSessionId: enriched.chatSessionId,
        mcpSessionId: enriched.mcpSessionId,
        planIndex: enriched.planIndex,
        planCount: enriched.planCount,
        planId: enriched.planId,
        subQuestion: enriched.subQuestion,
        question: enriched.question,
        selectedTool: enriched.selectedTool,
        requestArguments: enriched.requestArguments,
        ok: false,
        error: error.message || String(error)
      }
    };
  }
