// ============================================================
// Main Processing
// ============================================================

const output = [];

for (let index = 0; index < inputItems.length; index++) {
  const response = inputItems[index].json ?? {};

  // Match the originating request by JSON-RPC id; fall back to preserved metadata
  // and only then to item order.
  const matchedBuild =
    response.rpcId != null
      ? buildItems.find(item => item.json?.rpcId === response.rpcId)
      : null;

  const build = matchedBuild?.json;
  if (!build) {
    throw new Error("Format Result: response RPC ID has no matching originating plan.");
  }

  const selectedTool =
    response.selectedTool ??
