      out.push(english?"Course evidence (course_id, course_name): "+evidence:"شواهد درس (course_id، course_name): "+evidence);
    }
  }
  out.push("");
}
const failures=r.filter(x=>x.executionSuccess===false).length;
const semanticIntegrityFailures=r.filter(x=>x.semanticIntegrity?.status==="invalid");
const overallStatus=semanticIntegrityFailures.length>0?"integrity_failure":failures>0?"partial_failure":"success";
if(semanticIntegrityFailures.length){
 analysis=fa
  ?"تحلیل عددی نهایی ارائه نشد؛ اعتبارسنجی ساختاریافته حداقل یک نتیجه تجمیعی را نامعتبر تشخیص داد."
  :"The final numeric analysis was withheld because structured validation detected at least one invalid aggregate result.";
}

if(semanticIntegrityFailures.length){
  out.push(fa?"## هشدار یکپارچگی داده":"## Data integrity warning",fa?"تحلیل عددی نهایی به دلیل integrity_failure متوقف شد.":"Data integrity warning: final numeric analysis was withheld (integrity_failure).");
}
let output;
if(mode==="analysis"){
  output=includeAnalysis&&analysis?analysis:(english?"No evidence-based analysis was produced.":"تحلیل مستند تولید نشد.");
}else{
  if(includeAnalysis&&analysis)out.push(english?"## Analysis and interpretation":"## تحلیل و تفسیر نتایج","",analysis);
  output=numericOnly&&r.length===1&&r[0].executionSuccess===true&&r[0].countValue!=null?String(r[0].countValue):[english?"Results:":"نتایج درخواست شما:","",...out].join("\n").trim();
}
return [{json:{
  output,text:output,responseMode:mode,language,
  totalResults:r.length,
  successfulResults:r.filter(x=>x.executionSuccess===true).length,
  failedResults:failures,
  unrecognizedResults:r.filter(x=>x.executionSuccess===true&&x.recognized!==true).length,
  analysisIncluded:includeAnalysis,
  multiPlan:r.length>1
}}];

// Prepare LLM Context
// Version: 2.1
// Mode: Run Once for All Items

const items = $input.all().map(item => item.json);

if (items.length === 0) {
  throw new Error(
    "Prepare LLM Context: ورودی Format Result خالی است."
  );
}

// Safely parse JSON values.
function parseJson(value, fieldName) {
  if (value === undefined || value === null || value === "") {
    return null;
  }

  if (typeof value !== "string") {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch (error) {
    return {
      parse_error: true,
      field: fieldName,
      raw_value: value
    };
  }
}

// Return the first valid non-negative numeric value.
function getNumericValue(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      value !== "" &&
      Number.isFinite(Number(value)) &&
      Number(value) >= 0
    ) {
      return Number(value);
    }
  }

  return null;
}

// Validate the user's question.
const questions = [
  ...new Set(
    items
      .map(item => String(item.question ?? "").trim())
      .filter(Boolean)
  )
];

if (questions.length === 0) {
  throw new Error(
    "Prepare LLM Context: متن سؤال کاربر پیدا نشد."
  );
}

if (questions.length > 1) {
  throw new Error(
    "Prepare LLM Context: چند سؤال متفاوت در ورودی دریافت شد."
  );
}

const question = questions[0];
const responseMode = items[0].responseMode ?? "combined";
const request = $("Prepare Input").first()?.json ?? {};
const language = request.language ?? "und";
const persianCount = (question.match(/[\u0600-\u06FF]/g) ?? []).length;
const latinCount = (question.match(/[A-Za-z]/g) ?? []).length;
const responseLanguage = language;
const includeAnalysis = request.includeAnalysis === true;
const sessionId = request.sessionId ?? null;

const expectedPlanCount = Number(items[0].planCount ?? items.length);
if (!Number.isInteger(expectedPlanCount) || expectedPlanCount < 1 ||
    items.length !== expectedPlanCount) {
  throw new Error("Prepare LLM Context: plan response count does not match the submitted plan count.");
}
const planIndexes = items.map(item => Number(item.planIndex));
if (planIndexes.some(index => !Number.isInteger(index) || index < 0 || index >= expectedPlanCount) ||
    new Set(planIndexes).size !== expectedPlanCount ||
    [...planIndexes].sort((a,b)=>a-b).some((index,position)=>index!==position)) {
  throw new Error("Prepare LLM Context: plan indexes are missing, duplicated, or out of range.");
}
if (items.some(item => Number(item.planCount) !== expectedPlanCount)) {
  throw new Error("Prepare LLM Context: inconsistent planCount metadata.");
}
const planIds = items.map(item => String(item.planId ?? "").trim());
if (planIds.some(id => !id) || new Set(planIds).size !== expectedPlanCount) {
  throw new Error("Prepare LLM Context: plan IDs are missing or duplicated.");
}
const rpcIds = items.map(item => String(item.rpcId ?? "").trim());
if (rpcIds.some(id => !id) || new Set(rpcIds).size !== expectedPlanCount) {
  throw new Error("Prepare LLM Context: RPC IDs are missing or duplicated.");
}
if (items.some(item => (item.responseMode ?? "combined") !== responseMode)) {
  throw new Error("Prepare LLM Context: mixed response modes detected in one execution.");
}
const chatSessionIds = [...new Set(items.map(item => String(item.chatSessionId ?? "").trim()).filter(Boolean))];
if (chatSessionIds.length > 1) {
  throw new Error("Prepare LLM Context: mixed chat sessions detected in one execution.");
}
if (sessionId && chatSessionIds.length === 1 && chatSessionIds[0] !== sessionId) {
  throw new Error("Prepare LLM Context: chat session identity mismatch.");
}
const mcpSessionIds = [...new Set(items.map(item => String(item.mcpSessionId ?? "").trim()).filter(Boolean))];
if (mcpSessionIds.length > 1) {
  throw new Error("Prepare LLM Context: mixed MCP sessions detected in one execution.");
}
const expectedMcpSessionId = $("MCP Parse Init").first()?.json?.sessionId ?? null;
if (expectedMcpSessionId && mcpSessionIds.length === 1 && mcpSessionIds[0] !== expectedMcpSessionId) {
  throw new Error("Prepare LLM Context: MCP session identity mismatch.");
}
if (expectedMcpSessionId && (mcpSessionIds.length !== 1 || mcpSessionIds[0] !== expectedMcpSessionId)) {
  throw new Error("Prepare LLM Context: missing or mismatched MCP session identity.");
}
if (!expectedMcpSessionId && mcpSessionIds.length > 0 && items.some(item => !item.mcpSessionId)) {
  throw new Error("Prepare LLM Context: partial MCP session identity detected.");
}
if (sessionId && (chatSessionIds.length !== 1 || chatSessionIds[0] !== sessionId)) {
  throw new Error("Prepare LLM Context: missing or mismatched chat session identity.");
}
if (!sessionId && chatSessionIds.length > 0 && items.some(item => !item.chatSessionId)) {
  throw new Error("Prepare LLM Context: partial chat session identity detected.");
}
const mcpSessionId = mcpSessionIds[0] ?? expectedMcpSessionId;

// Normalize each MCP plan independently.
const results = items.map((item, index) => {

  const parsedFacts = parseJson(
    item.factsJson ?? item.facts,
    "factsJson"
  );

  const executedQuery = parseJson(
    item.queryJson ?? item.executedQuery,
    "queryJson"
  );

  const facts =
    parsedFacts &&
    typeof parsedFacts === "object" &&
    !Array.isArray(parsedFacts)
      ? parsedFacts
      : null;

  // Execution status is independent of plan recognition.
  let executionStatus = "unknown";

  if (typeof item.executionSuccess === "boolean") {
    executionStatus = item.executionSuccess
      ? "success"
      : "failure";
  } else if (typeof item.success === "boolean") {
    executionStatus = item.success
      ? "success"
      : "failure";
  } else if (item.error) {
    executionStatus = "failure";
  }

  // Full structured records must be supplied by Format Result
  // under facts.rows.
  const fullRows = Array.isArray(facts?.rows)
    ? facts.rows
    : null;

  // rows_sample is only a preview, not a replacement for rows.
  const sampleRows = Array.isArray(facts?.rows_sample)
    ? facts.rows_sample
    : [];

  const expectedRecords = getNumericValue(
    item.totalRecords,
    facts?.total_records,
    item.rowCount,
    facts?.row_count,
    item.shown,
    facts?.shown
  );

  const availableRecords = fullRows
    ? fullRows.length
    : sampleRows.length;

  // COUNT is a scalar; AGGREGATE rows are buckets. Neither is a
  // document sample and neither can establish source-index completeness.
  let completenessStatus = "not_applicable";
  let responseLimited = false;

  if (item.operation === "select") {
    if (fullRows !== null) {
      if (expectedRecords === null) {
        completenessStatus = "available_unverified";
      } else if (fullRows.length >= expectedRecords) {
        completenessStatus = "complete";
      } else {
        completenessStatus = "partial_response";
        responseLimited = true;
      }
    } else if (sampleRows.length > 0) {
      completenessStatus = "sample_only";
      responseLimited = true;
    } else {
      completenessStatus = "unknown";
    }
  }

  return {
    result_index: index + 1,

    tool: item.selectedTool ?? "unknown",
    operation: item.operation ?? null,

    plan_status: {
      recognized: item.recognized === true,
      execution_status: executionStatus,
      error: item.error ?? null
    },

    data_statistics: {
      row_count: getNumericValue(
        item.rowCount,
        facts?.row_count
      ),

      total_records: getNumericValue(
        item.totalRecords,
        facts?.total_records
      ),

      shown: getNumericValue(
        item.shown,
        facts?.shown
      ),

      count_value: item.countValue ?? facts?.count ?? null
    },

    record_semantics:
      item.operation === "count"
        ? "scalar_count"
        : item.operation === "aggregate"
          ? "aggregation_buckets"
          : item.operation === "select"
            ? "selected_documents"
            : "tool_specific",

    data_completeness: {
      status: completenessStatus,
      expected_records: expectedRecords,
      available_records: availableRecords,
      structured_rows_available: fullRows !== null,
      response_limited: responseLimited,
      dataset_completeness: "not_assessed",
      is_complete: completenessStatus === "complete" ? true : null
    },

    // Preserve all original facts.
    // Full records are expected in facts.rows.
    facts: facts ?? parsedFacts,

    executed_query: executedQuery,

    display_reference: {
      table_markdown: item.tableMarkdown ?? ""
    }
  };
});

// Calculate context-level statistics.
const recognizedPlans = results.filter(
  result => result.plan_status.recognized
).length;

const successfulExecutions = results.filter(
  result => result.plan_status.execution_status === "success"
).length;

const failedExecutions = results.filter(
  result => result.plan_status.execution_status === "failure"
).length;

const unknownExecutions = results.filter(
  result => result.plan_status.execution_status === "unknown"
).length;

const completeResults = results.filter(
  result => result.data_completeness.status === "complete"
).length;

const limitedResults = results.filter(
  result => result.data_completeness.response_limited === true
).length;

// Build unified analytical context.
const context = {
  context_version: "3.0",

  question,
  response_mode: responseMode,
  response_language: language,
  responseLanguage,
  persianCount,
  latinCount,
  session_id: sessionId,
  mcp_session_id: mcpSessionId,

  metadata: {
    total_plans: results.length,

    recognized_plans: recognizedPlans,
    unrecognized_plans: results.length - recognizedPlans,

    successful_executions: successfulExecutions,
    failed_executions: failedExecutions,
    unknown_executions: unknownExecutions,

    complete_results: completeResults,
    limited_results: limitedResults,
    incomplete_results: 0
  },

  analytical_instructions: {
    source_of_truth: "MCP tool results",

    rules: [
      "Use only the supplied MCP results.",
      "Analyze all available plans.",
      "Compare related results across tools when relevant to the user's question.",
      "Distinguish observed facts from analytical inferences.",
      "Do not invent missing values or records.",
      "Do not treat unknown execution status as success.",
      "Identify incomplete or failed results.",
      "Use executed queries to understand result scope.",
      "Use facts.rows as the authoritative structured record collection.",
      "Never treat rows_sample as the complete dataset.",
      "COUNT values are scalar summaries; never compare their one-row representation with source document totals.",
      "AGGREGATE rows are buckets; never compare bucket count with source document totals to infer dataset completeness.",
      "A limited SELECT response is not proof that the underlying dataset is incomplete.",
      "Dataset completeness is not assessed by this workflow.",
      "Do not infer that missing sample records do not exist.",
      "Do not reproduce complete tables unless requested by the user."
    ]
  },

  results
};

// Preserve downstream compatibility.
const serializedContext = JSON.stringify(context, null, 2);

return [
  {
    json: {
      question,
      responseMode,
      language,
      responseLanguage,
      persianCount,
      latinCount,
      includeAnalysis,
      sessionId,
      mcpSessionId,

      recognized:
        recognizedPlans === results.length,

      totalPlans: results.length,

      successfulExecutions,
      failedExecutions,
      unknownExecutions,

      factsJson: serializedContext,
      contextJson: serializedContext
    }
  }
];

const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode ?? 0);
const accepted = Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300;
const body = String(response.body ?? response.data ?? "").trim().slice(0, 1000);
const error = accepted ? null : `MCP initialized notification failed (HTTP ${statusCode || "unknown"}). ${body}`.trim();
return [{ json: { ok: accepted, statusCode, error } }];
